      "id": "gothic_witness",
      "title": "Witness at the Gate",
      "description": "A short clue dialogue.",
      "npc_id": "npc/gate_witness",
      "scene_id": "scene/market_gate",
      "lines": [
        "I saw the silver key vanish by the old gate."
      ],
      "start_node_id": "start",
      "nodes": [
        {
          "id": "start",
          "speaker_id": "npc/gate_witness",
          "text": "You are asking about the key?",
          "choices": [
            {
              "id": "ask_key",
              "text": "Tell me what you saw.",
              "target_node_id": "clue",
              "start_quest_id": "quest/gothic/clue/thread"
            }
          ]
        },
        {
          "id": "clue",
          "speaker_id": "npc/gate_witness",
          "text": "A courier carried it toward the chapel.",
          "choices": [
            {
              "id": "accept_clue",
              "text": "I will follow the trail.",
              "close_dialogue": true,
              "advance_quest_id": "quest/gothic/clue/thread",
              "set_quest_stage_id": "interrogate"
            }
          ]
        }
      ]
    }
  ],
  "source_context": {
    "capability_selection_id": "generator_plan_capability_selection/64aa7f054a697e50"
  }
}

